"""Synthetic trust-boundary tests. No live services or secrets required."""
import json
import shutil
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

ORIGINAL = Path(__file__).resolve().parent
# Supplied by a different, trusted fixture rather than generated by runner.py.
PINNED_TRUST_ROOT_SHA256 = "73d86bf1d7d411054a44df086776b7237753878984338e8023f7463291dd1d5d"
PINNED_VERIFIER_SHA256 = "8a543194ec688a9b10e8e628940eedde97eb190c8cea3a38211f9c8ed5c481b3"
TEST_KEY = "demonstration-test-key-NOT-REAL-SECRET"

class Chapter2TrustTests(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.addCleanup(self.temp.cleanup)
        self.here = Path(self.temp.name) / "lab"
        shutil.copytree(ORIGINAL, self.here, ignore=shutil.ignore_patterns("__pycache__", "*.pyc"))
        self.out = Path(self.temp.name) / "results"
        self.manifest = self.out / "manifest.json"
        self.attestation = self.out / "attestation.json"

    def run_command(self, name, *args, ok=True):
        p = subprocess.run([sys.executable, str(self.here / name), *map(str, args)],
                           capture_output=True, text=True, cwd=self.temp.name,
                           env={"PATH": "/usr/bin:/bin", "MOSAIC_ATTESTATION_KEY": TEST_KEY})
        if ok and p.returncode != 0:
            self.fail(p.stdout + "\n" + p.stderr)
        if not ok:
            self.assertNotEqual(p.returncode, 0)
        return p

    def check_verifier_pin(self):
        import hashlib
        if hashlib.sha256((self.here / "verify.py").read_bytes()).hexdigest() != PINNED_VERIFIER_SHA256:
            raise ValueError("independently pinned verifier has changed")

    def generate(self):
        self.run_command("runner.py", "--output", self.manifest)

    def sign(self):
        self.check_verifier_pin()
        self.run_command("verify.py", "--manifest", self.manifest,
                         "--approval", self.here / "trusted_approval.json",
                         "--anchor-sha256", PINNED_TRUST_ROOT_SHA256,
                         "--attestation", self.attestation)

    def check(self, ok=True):
        self.check_verifier_pin()
        return self.run_command("verify.py", "--manifest", self.manifest,
                                "--approval", self.here / "trusted_approval.json",
                                "--anchor-sha256", PINNED_TRUST_ROOT_SHA256,
                                "--attestation", self.attestation,
                                "--check-only", ok=ok)

    def test_baseline_green_candidate_red_signed_and_verified(self):
        self.generate()
        self.sign()
        self.check()
        result = json.loads(self.manifest.read_text())
        self.assertEqual(result["outcomes"]["baseline"]["decision"], "GREEN")
        self.assertEqual(result["outcomes"]["candidate"]["decision"], "RED")
        self.assertEqual(result["outcomes"]["baseline"]["correct"], 2)
        self.assertEqual(result["outcomes"]["candidate"]["correct"], 3)

    def test_manifest_cannot_be_silently_overwritten(self):
        self.generate()
        self.run_command("runner.py", "--output", self.manifest, ok=False)

    def test_manifest_postwrite_tampering_detected(self):
        self.generate()
        self.sign()
        data = json.loads(self.manifest.read_text())
        data["outcomes"]["candidate"]["decision"] = "GREEN"
        self.manifest.write_text(json.dumps(data))
        self.check(ok=False)

    def test_scorer_mutation_is_blocked_by_external_approval(self):
        self.generate()
        (self.here / "scorer.py").write_text((self.here / "scorer.py").read_text() + "\n# unapproved modification\n")
        self.run_command("verify.py", "--manifest", self.manifest,
                         "--approval", self.here / "trusted_approval.json",
                         "--anchor-sha256", PINNED_TRUST_ROOT_SHA256,
                         "--attestation", self.attestation, ok=False)

    def test_policy_and_selfapproved_manifest_cannot_bypass_pin(self):
        self.generate()
        policy = self.here / "policy.json"
        data = json.loads(policy.read_text())
        data["max_unsafe"] = 1
        policy.write_text(json.dumps(data))
        approval = self.here / "trusted_approval.json"
        changed = json.loads(approval.read_text())
        import hashlib
        changed["expected_sha256"]["policy"] = hashlib.sha256(policy.read_bytes()).hexdigest()
        approval.write_text(json.dumps(changed))
        self.run_command("verify.py", "--manifest", self.manifest,
                         "--approval", approval,
                         "--anchor-sha256", PINNED_TRUST_ROOT_SHA256,
                         "--attestation", self.attestation, ok=False)

    def test_fake_attestation_is_not_accepted(self):
        self.generate()
        self.sign()
        data = json.loads(self.attestation.read_text())
        data["signature_hmac_sha256"] = "0" * 64
        self.attestation.write_text(json.dumps(data))
        self.check(ok=False)

    def test_empty_key_cannot_verify_attestation(self):
        self.generate()
        self.sign()
        from unittest.mock import patch
        with patch.object(__import__("os"), "environ", {"PATH": "/usr/bin:/bin", "MOSAIC_ATTESTATION_KEY": ""}):
            p = __import__("subprocess").run([__import__("sys").executable, str(self.here / "verify.py"), "--manifest", str(self.manifest), "--approval", str(self.here / "trusted_approval.json"), "--anchor-sha256", PINNED_TRUST_ROOT_SHA256, "--attestation", str(self.attestation), "--check-only"], capture_output=True, text=True)
            self.assertNotEqual(p.returncode, 0)

    def test_verifier_mutation_rejected(self):
        self.generate()
        v = self.here / "verify.py"
        v.write_text(v.read_text() + "\n# unauthorized verifier change\n")
        with self.assertRaises(ValueError):
            self.sign()

    def test_runner_mutation_detected_independently(self):
        self.generate()
        file = self.here / "runner.py"
        file.write_text(file.read_text() + "\n# unapproved runner change\n")
        self.run_command("verify.py", "--manifest", self.manifest,
                         "--approval", self.here / "trusted_approval.json",
                         "--anchor-sha256", PINNED_TRUST_ROOT_SHA256,
                         "--attestation", self.attestation, ok=False)

if __name__ == "__main__":
    unittest.main()
